+  // We check again to account for changes during the jscall
+  fast = EnsureJSArrayWithWritableFastElements(isolate, array_object, nullptr, 0, 0);
+
+  // 11. Perform Set(O, n, replacement)
+  if (fast) {
+    // Fast path (packed elements)
